  function renderDoctorActivity(id){const d=doctors.find(x=>x.id===id),view=document.querySelector('#doctorProfileView'),from=view.querySelector('#doctorActivityFrom').value||d.joiningDate,to=view.querySelector('#doctorActivityTo').value||isoDate(new Date()),host=view.querySelector('#doctorActivitySummary');let total=daysBetween(from,to),limit=total>370?370:total,rows=[];for(let i=0;i<limit;i++){const date=isoDate(addDays(new Date(to+'T12:00:00'),-i));if(date<from)break;rows.push(daySummary(d,date))}const older=total>limit?`<div class="notice"><strong>Long service range:</strong> showing the latest ${limit} daily rows. Use a narrower custom period to inspect earlier dates from ${new Date(d.joiningDate).toLocaleDateString('en-IN')} onward.</div>`:'';host.innerHTML=older+`<div class="table-wrap"><table><thead><tr><th>Date</th><th>Logins</th><th>Patients</th><th>Appointments</th><th>Records</th><th>Prescriptions</th><th>Reports</th><th>Downloads</th><th>Alerts</th><th>Risk</th></tr></thead><tbody>${rows.map(x=>`<tr class="activity-date-row" onclick="window.adminViewDoctorDay('${esc(d.id)}','${x.date}')"><td><button class="date-link">${new Date(x.date+'T12:00:00').toLocaleDateString('en-IN',{day:'2-digit',month:'short',year:'numeric'})}</button></td><td>${x.logins}</td><td>${x.patients}</td><td>${x.appointments}</td><td>${x.records}</td><td>${x.prescriptions}</td><td>${x.reports}</td><td>${x.downloads}</td><td>${x.alerts}</td><td><span class="badge ${x.risk==='Low'?'low':x.risk==='Medium'?'medium':x.risk==='High'?'high':'critical'}">${x.risk}</span></td></tr>`).join('')}</tbody></table></div>`;}
  window.adminViewDoctorDay=(id,date)=>{const d=doctors.find(x=>x.id===id),rows=activityRows(d,date),host=document.querySelector('#doctorActivityDetail');host.innerHTML=`<div class="record-header"><div><span class="eyebrow">Daily activity investigation</span><h2>${esc(d.name)} · ${new Date(date+'T12:00:00').toLocaleDateString('en-IN',{dateStyle:'long'})}</h2><p>Click any activity to inspect the complete device, network, risk, and response context.</p></div><button class="button secondary" onclick="window.print()">Print day</button></div><div class="table-wrap"><table><thead><tr><th>Time</th><th>Activity</th><th>Module</th><th>Patient / File</th><th>Device</th><th>IP Address</th><th>Location</th><th>Result</th><th>Risk</th></tr></thead><tbody>${rows.map((r,i)=>`<tr class="activity-date-row" onclick="window.adminViewActivityDetail('${esc(id)}','${date}',${i})">${r.map((v,j)=>`<td>${j===8?`<span class="badge ${v==='Low'?'low':v==='High'?'high':'critical'}">${esc(v)}</span>`:esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><div id="singleActivityDetail"></div>`;host.scrollIntoView({behavior:'smooth',block:'start'})};
  window.adminViewActivityDetail=(id,date,index)=>{const d=doctors.find(x=>x.id===id),r=activityRows(d,date)[index],host=document.querySelector('#singleActivityDetail');host.innerHTML=`<div class="activity-inspector"><div><span>Exact date and time</span><strong>${new Date(date+'T12:00:00').toLocaleDateString('en-IN',{dateStyle:'long'})} · ${esc(r[0])}</strong></div><div><span>Doctor</span><strong>${esc(d.name)} (${esc(d.id)})</strong></div><div><span>Action</span><strong>${esc(r[1])}</strong></div><div><span>Module</span><strong>${esc(r[2])}</strong></div><div><span>Patient / file</span><strong>${esc(r[3])}</strong></div><div><span>Device</span><strong>${esc(r[4])}</strong></div><div><span>IP and location</span><strong>${esc(r[5])} · ${esc(r[6])}</strong></div><div><span>Result</span><strong>${esc(r[7])}</strong></div><div><span>AI risk</span><strong>${esc(r[8])}</strong></div><div class="inspector-wide"><span>AI explanation and mitigation</span><strong>${r[8]==='Critical'?' deviated sharply from the doctor’s learned baseline. Sensitive records were restricted, verification was required, the session was terminated, and incident INC-0025 was recorded.':'Activity is consistent with the doctor’s established working hours, device, location, and clinical-access volume.'}</strong></div></div>`;host.scrollIntoView({behavior:'smooth',block:'nearest'})};
  window.adminLoadExportedDetails=async doctorId=>{const host=document.querySelector('#doctorExportedDetailsPanel');if(!host)return;host.innerHTML='<div class="empty-row">Loading exported details...</div>';try{const token=sessionStorage.getItem('htd_token');const res=await fetch('/api/communication/exported-details',{headers:{Authorization:'Bearer '+token}});const d=await res.json();if(!res.ok)throw new Error(d.message||'Unable to load exported details');const rows=(d.exports||[]).filter(x=>String(x.doctor_id||'')===String(doctorId));host.innerHTML=`<article class="panel"><div class="panel-heading"><h3>Exported Details</h3></div><div class="table-wrap"><table><thead><tr><th>Date & Time</th><th>Patient / File</th><th>Section</th><th>Reason</th><th>Status</th><th></th></tr></thead><tbody>${rows.length?rows.map(x=>`<tr><td>${new Date((x.exported_at||'').replace(' ','T')+'Z').toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})}</td><td>${esc(x.patient||x.item||'Record')}<br><small>${esc(x.item||'')}</small></td><td>${esc(x.section||'')}</td><td>${esc(x.reason==='Other'?(x.other_reason||'Other'):x.reason)}</td><td>${esc(x.admin_status||'Pending')}</td><td><button class="small-btn" onclick="window.adminViewExportDetail(${x.id})">View</button> ${x.admin_status==='Acknowledged'?'':`<button class="small-btn" onclick="window.adminAcknowledgeExport(${x.id},'${esc(doctorId)}')">Acknowledge</button>`}</td></tr>`).join(''):'<tr><td colspan="6">No single-record exports logged for this doctor.</td></tr>'}</tbody></table></div></article>`;}catch(e){host.innerHTML=`<div class="notice">${esc(e.message)}</div>`;}};
  window.adminViewExportDetail=async id=>{try{const token=sessionStorage.getItem('htd_token');const res=await fetch('/api/communication/exported-details',{headers:{Authorization:'Bearer '+token}});const d=await res.json();const x=(d.exports||[]).find(r=>Number(r.id)===Number(id));if(!x)return alert('Export detail not found');alert(`Doctor: ${x.doctor_name}\nPatient / File: ${x.patient||x.item}\nData: ${x.item||x.section}\nReason: ${x.reason==='Other'?(x.other_reason||'Other'):x.reason}\nDate/Time: ${new Date((x.exported_at||'').replace(' ','T')+'Z').toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})}\nAdmin: ${x.admin_status||'Pending'}`);}catch(e){alert(e.message)}};
  window.adminAcknowledgeExport=async(id,doctorId)=>{try{const token=sessionStorage.getItem('htd_token');const res=await fetch(`/api/communication/exported-details/${id}/acknowledge`,{method:'POST',headers:{Authorization:'Bearer '+token}});const d=await res.json();if(!res.ok)throw new Error(d.message||'Unable to acknowledge');showToast('Export notification acknowledged.');window.adminLoadExportedDetails(doctorId);}catch(e){alert(e.message)}};
  window.adminExportDoctorActivity=id=>{const d=doctors.find(x=>x.id===id),to=isoDate(new Date()),from=isoDate(addDays(new Date(),-29)),rows=[];for(let i=0;i<30;i++)rows.push(daySummary(d,isoDate(addDays(new Date(),-i))));downloadCsv(`${d.id}-${d.name.replace(/[^a-z0-9]+/gi,'-').toLowerCase()}-activity.csv`,['date','logins','patients','appointments','records','prescriptions','reports','downloads','alerts','risk'],rows);showToast(`${d.name} activity exported.`)};
  function editDoctor(id){const d=doctors.find(x=>x.id===id)||{id:`D${String(doctors.length+1).padStart(3,'0')}`,name:'',department:'General Medicine',position:'Consultant',qualification:'MBBS, MD',joiningDate:isoDate(new Date()),experience:'5 years',shift:'08:00 AM – 05:00 PM',phone:'',email:'',status:'Active',patients:0,normalLogin:'08:00',normalLogout:'17:00',avgRecords:20,avgDownloads:1,knownDevices:['Hospital workstation'],knownLocation:'WeCare Hospital Network',behaviorScore:95,risk:'Low'};modalShell(id?'Edit doctor':'Add doctor',field('id','Doctor ID',d.id)+field('name','Full name',d.name)+selectField('department','Department',d.department,['General Medicine','Cardiology','Neurology','Orthopedics','Radiology','Pediatrics','Emergency'])+field('position','Position',d.position)+field('qualification','Qualification',d.qualification)+field('joiningDate','Joining date',d.joiningDate,'date')+field('experience','Experience',d.experience)+field('shift','Normal shift',d.shift)+field('phone','Phone',d.phone)+field('email','Email',d.email,'email')+selectField('status','Status',d.status,['Active','On Leave','Inactive'])+field('patients','Assigned patients',d.patients,'number','min="0"'),data=>{data.patients=Number(data.patients);Object.assign(data,{normalLogin:d.normalLogin,normalLogout:d.normalLogout,avgRecords:d.avgRecords,avgDownloads:d.avgDownloads,knownDevices:d.knownDevices,knownLocation:d.knownLocation,behaviorScore:d.behaviorScore,risk:d.risk});const i=doctors.findIndex(x=>x.id===id);if(i>=0)doctors[i]=data;else doctors.unshift(data);saveDoctors();selectedDoctorId=null;renderDoctors();showToast(`Doctor ${id?'updated':'added'} successfully.`)})}
