  function editMedicine(id){const r=medicines.find(x=>x.id===id)||{id:`MED-${String(medicines.length+1).padStart(3,'0')}`,name:'',category:'General',stock:0,reorder:10,expiry:'2027-01',supplier:'',status:'Available'};modalShell(id?'Edit medicine':'Add medicine',field('id','Medicine ID',r.id)+field('name','Medicine name and strength',r.name)+field('category','Category',r.category)+field('stock','Current stock',r.stock,'number','min="0"')+field('reorder','Reorder level',r.reorder,'number','min="0"')+field('expiry','Expiry (YYYY-MM)',r.expiry)+field('supplier','Supplier',r.supplier)+selectField('status','Status override',r.status,['Available','Low Stock','Expiring Soon','Out of Stock']),data=>{data.stock=Number(data.stock);data.reorder=Number(data.reorder);const i=medicines.findIndex(x=>x.id===id);if(i>=0)medicines[i]=data;else medicines.unshift(data);saveMedicines();renderPharmacy();showToast(`Medicine ${id?'updated':'added'}.`)})}
