  let requests=[{doctor:'Dr. Arjun Kumar',device:'Windows Desktop',location:'Coimbatore',risk:'High',remaining:60,status:'Waiting',action:'Sensitive access restricted'},{doctor:'Dr. Kavitha',device:'Android Tablet',location:'Chennai',risk:'Medium',remaining:42,status:'Waiting',action:'Verification in progress'}];
