      const today=new Date().toISOString().slice(0,10);el.querySelector('#reportTo').value=today;el.querySelector('#reportFrom').value=new Date(Date.now()-6*86400000).toISOString().slice(0,10);el.querySelector('#reportCategory').onchange=renderReports;el.querySelector('#reportApply').onclick=()=>{renderReports();showToast('Report filters applied.')};el.querySelector('#reportsPrint').onclick=()=>window.print();el.querySelector('#reportsExportAll').onclick=exportSummaryReport;
