  window.adminVerify=(index,approved)=>{const r=requests[index];if(!r||r.status!=='Waiting')return;r.status=approved?'Approved':'Rejected';r.remaining=0;r.action=approved?'Session continued; sensitive access restored':'Session terminated; device restricted; incident created';mitigations.unshift([new Date().toLocaleTimeString('en-IN',{timeZone:'Asia/Kolkata',hour:'2-digit',minute:'2-digit'}),r.doctor,approved?'Administrator review approved':'Administrator review rejected',approved?'Restore session access':'Terminate session, restrict device, create incident','Completed']);renderMitigations();renderRequests();addAudit(r.doctor,approved?'Administrator restored access':'Administrator maintained restriction','Authentication',approved?'Approved':'Rejected',r.device);showToast(`${r.doctor}: request ${approved?'approved':'rejected'}.`)};

